INSERT INTO pt_log (
    usageId, memNum, empNum, status, countChange, createdAt, salesId, regId
)
SELECT
    #{usageId}, #{memNum}, #{empNum}, '소비', -1, SYSDATE, NULL, #{regId, jdbcType=NULL}
FROM dual
WHERE (
    SELECT NVL(SUM(countChange), 0)
    FROM pt_log
    WHERE memNum = #{memNum}
) > 0

mapper.select:
SELECT NVL(SUM(
    CASE
        WHEN status = '소비' THEN 1                 
        WHEN status = '예약취소' THEN -1           
        WHEN status = '부분환불' THEN ABS(countChange)   
        WHEN status = '전체환불' THEN ABS(countChange) 
        ELSE 0
    END
), 0) AS usedCount
FROM pt_log
WHERE memNum = #{memNum}
  AND (
       salesId = #{salesId}                
    OR (
          usageId > (
              SELECT MIN(usageId)
              FROM pt_log
              WHERE memNum = #{memNum}
                AND salesId = #{salesId}
                AND status = '충전'
          )
       )
  )

SELECT P.usageId, P.memNum, M.memName AS memberName, P.empNum, E.empName AS empName, P.status, P.countChange, TO_CHAR(P.createdAt, 'YYYY-MM-DD HH24:MI:SS') AS createdAt FROM ( SELECT usageId, rn FROM ( SELECT k.usageId, ROWNUM AS rn FROM ( SELECT P.usageId FROM pt_log P WHERE 1=1
AND P.usageId < #{cursor}
AND P.createdAt >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND P.createdAt < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND P.memNum = #{memNum}
AND P.empNum = #{empNum}
ORDER BY P.usageId DESC ) k WHERE ROWNUM <= #{endRow} ) WHERE rn > #{offset} ) pg JOIN pt_log P ON P.usageId = pg.usageId LEFT JOIN member M ON M.memNum = P.memNum LEFT JOIN employee E ON E.empNum = P.empNum ORDER BY pg.rn

SELECT COUNT(*) FROM pt_log P WHERE 1=1
AND P.createdAt >= TO_DATE(#{startDate}, 'YYYY-MM-DD')
AND P.createdAt < TO_DATE(#{endDate}, 'YYYY-MM-DD') + 1
AND P.memNum = #{memNum}
AND P.empNum = #{empNum}
